  ('Values Education', 7, 'G7-001', 'Nakapagsasanay sa maingat na paghuhusga sa pamamagitan ng pangingilatis sa katotohanan at kabutihan na nakapaloob sa isang situwasyon - Natutukoy ang mga katangian, gamit at tunguhin ng isip at kilos-loob', 1, '1 to 2 (10 days)', NULL),
  ('Values Education', 7, 'G7-002', 'Nakapagsasanay sa maingat na paghuhusga sa pamamagitan ng pangingilatis sa katotohanan at kabutihan na nakapaloob sa isang situwasyon - Naipaliliwanag na ang gamit ng isip at kilos-loob sa sariling pagpapasiya at pagkilos ay ang nagsisilbing gabay sa pagpili at pagkilos na alisunod sa katotohanan at kabutihan, dahil ang mga ito ang nagpapabukod-tangi sa kaniya sa ibang nilalang', 1, '1 to 2 (10 days)', NULL),
  ('Values Education', 7, 'G7-003', 'Nakapagsasanay sa maingat na paghuhusga sa pamamagitan ng pangingilatis sa katotohanan at kabutihan na nakapaloob sa isang situwasyon - Nailalapat ang wastong gamit ng isip at kilos-loob sa mga sariling pagpapasiya at pagkilos alinsunod sa katotohanan at kabutihan', 1, '1 to 2 (10 days)', NULL),
  ('Values Education', 7, 'G7-004', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng pakikibahagi sa mga gawaing magpapabuti sa sarili, pamilya, at kapuwa - Nakakikilala na ang dignidad ay ang batayan ng paggalang sa sarili, pamilya, at kapuwa', 1, '3', NULL),
  ('Values Education', 7, 'G7-005', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng pakikibahagi sa mga gawaing magpapabuti sa sarili, pamilya, at kapuwa - Naipaliliwanag na ang dignidad ng tao bilang batayan ng paggalang sa sarili, pamilya, at kapuwa ay ang nagpapantay-pantay sa lahat ng tao dahil sa taglay niyang isip at kilos-loob, at ito ang nagbubunsod sa kaniya na gumawa ng mabuti', 1, '3', NULL),
  ('Values Education', 7, 'G7-006', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng pakikibahagi sa mga gawaing magpapabuti sa sarili, pamilya, at kapuwa - Nakapaglalapat ng mga sariling kilos ng pagkilala sa dignidad ng sarili, pamilya, at kapuwa', 1, '3', NULL),
  ('Values Education', 7, 'G7-007', 'Nakapagsasanay sa pagiging matatag sa pamamagitan ng palagiang paninindigan sa mga taglay na pagpapahalaga at virtue - Nakakikilala ng mga paraan ng paggamit ng pagpapahalaga at virtue bilang batayan ng sariling pagpapasiya, pagkilos, at pakikipagkapuwa', 1, '4 to 5 (10 days)', NULL),
  ('Values Education', 7, 'G7-008', 'Nakapagsasanay sa pagiging matatag sa pamamagitan ng palagiang paninindigan sa mga taglay na pagpapahalaga at virtue - Naipaliliwanag na ang pagpapahalaga at virtue bilang batayan ng sariling pagpapasiya, pagkilos, at pakikipagkapuwa ay gabay na magtitiyak na patungo sa katotohanan at kabutihan ang bawat pagtugon lalo na sa mga situwasyon na sinusubok ang kanilang pagkatao', 1, '4 to 5 (10 days)', NULL),
  ('Values Education', 7, 'G7-009', 'Nakapagsasanay sa pagiging matatag sa pamamagitan ng palagiang paninindigan sa mga taglay na pagpapahalaga at virtue - Nailalapat nang wasto ang pagpapahalaga at virtue sa mga gagawing pagpapasiya, pagkilos, at pakikipagkapuwa', 1, '4 to 5 (10 days)', NULL),
  ('Values Education', 7, 'G7-010', 'Nakapagsasanay sa pananalig sa Diyos sa pamamagitan ng pagbabahagi ng positibong pananaw sa pagharap sa mga hamon sa buhay - Natutukoy ang mahalagang papel ng sariling pananampalataya sa buhay', 1, '6 to 7 (10 days)', NULL),
  ('Values Education', 7, 'G7-011', 'Nakapagsasanay sa pananalig sa Diyos sa pamamagitan ng pagbabahagi ng positibong pananaw sa pagharap sa mga hamon sa buhay - Naipaliliwanag na ang sariling pananampalataya sa Diyos ay nakatutulong sa pagkakaroon ng pag-asa, katatagan, at lakas ng loob (courage) sa pagharap sa mga hamon sa buhay', 1, '6 to 7 (10 days)', NULL),
  ('Values Education', 7, 'G7-012', 'Nakapagsasanay sa pananalig sa Diyos sa pamamagitan ng pagbabahagi ng positibong pananaw sa pagharap sa mga hamon sa buhay - Nailalapat ang sariling pananampalataya sa Diyos sa lahat ng oras lalo na sa mga mapanghamong situwasyon (hal. positibong pananaw sa kabila ng kahirapan)', 1, '6 to 7 (10 days)', NULL),
  ('Values Education', 7, 'G7-013', 'Nakapagsasanay sa pagiging mabuting katiwala sa pamamagitan ng pagsisinop ng lahat ng bagay upang mapakinabangan hindi lamang ng sarili kundi ng kapuwa at pamayanan - Nakapag-uugnay sa kahalagahan ng pagtitipid at pag- iimpok sa sariling pangangasiwa sa mga biyaya ng Diyos', 1, '8 to 9 (10 days)', NULL),
  ('Values Education', 7, 'G7-014', 'Nakapagsasanay sa pagiging mabuting katiwala sa pamamagitan ng pagsisinop ng lahat ng bagay upang mapakinabangan hindi lamang ng sarili kundi ng kapuwa at pamayanan - Naipaliliwanag na ang pagtitipid at pag-iimpok bilang sariling pangangasiwa sa mga biyaya ng Diyos ay pagiging mabuting katiwala ng mga kaloob Niya na magagamit sa pagtulong sa kapuwa at pamayanan', 1, '8 to 9 (10 days)', NULL),
  ('Values Education', 7, 'G7-015', 'Nakapagsasanay sa pagiging mabuting katiwala sa pamamagitan ng pagsisinop ng lahat ng bagay upang mapakinabangan hindi lamang ng sarili kundi ng kapuwa at pamayanan - Naisasakilos ang pagtitipid at pag-iimpok upang tulungan ang kapuwa at pamayanan ayon sa sariling kakayahan', 1, '8 to 9 (10 days)', NULL),
  ('Values Education', 7, 'G7-016', 'Nakapagsasanay sa kahandaan sa pamamagitan ng pagkakaroon ng emergency kit o katumbas nito batay sa sariling kakayahan - Nakakikilala ng mga wastong pagtugon sa panahon ng kalamidad', 1, '10 (5 days)', NULL),
  ('Values Education', 7, 'G7-017', 'Nakapagsasanay sa kahandaan sa pamamagitan ng pagkakaroon ng emergency kit o katumbas nito batay sa sariling kakayahan - Naipaliliwanag na ang pansariling pagtugon sa panahon ng kalamidad ay paraan upang mailigtas ang buhay, malinang ang kahandaan sa pagharap sa mga panganib, mabawasan ang posibleng pagdurusa ng tao at makatulong sa kaligtasan ng kapuwa alinsunod sa mga alituntunin ng awtoridad', 1, '10 (5 days)', NULL),
  ('Values Education', 7, 'G7-018', 'Nakapagsasanay sa kahandaan sa pamamagitan ng pagkakaroon ng emergency kit o katumbas nito batay sa sariling kakayahan - Nailalapat ang mga pansariling pagtugon sa panahon ng kalamidad', 1, '10 (5 days)', NULL),
  ('Values Education', 7, 'G7-019', 'Nakapagsasanay sa pagigng mapanagutan sa pamamagitan ng panghihikayat sa iba na gampanan ang kanilang mga tungkulin bilang mamamayan - Nakapagpapahayag ng mga paraan sa pagtupad ng sariling tungkulin bilang mamamayan', 1, '11 (5 days)', NULL),
  ('Values Education', 7, 'G7-020', 'Nakapagsasanay sa pagigng mapanagutan sa pamamagitan ng panghihikayat sa iba na gampanan ang kanilang mga tungkulin bilang mamamayan - Naipaliliwanag na ang pagtupad ng sariling tungkulin bilang mamamayan ay pakikibahagi niya sa pagpapabuti at pagpapatatag ng bayan para sa kapakinabangan ng mga mamamayan', 1, '11 (5 days)', NULL),
  ('Values Education', 7, 'G7-021', 'Nakapagsasanay sa pagigng mapanagutan sa pamamagitan ng panghihikayat sa iba na gampanan ang kanilang mga tungkulin bilang mamamayan - Nailalapat ang mga paraan ng pagtupad ng sariling tungkulin bilang mamamayan tulad ng paggalang sa mga karapatan ng kapuwa, pagsunod sa mga batas, pagiging mabuting pinuno, at tagasunod', 1, '11 (5 days)', NULL),
  ('Values Education', 7, 'G7-022', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng palagiang pagsangguni sa mga magulang o tagapangalaga tungkol sa mga karanasan kaugnay ng mga natutuhang pagpapahalaga - Natutukoy ang mga pagpapahalagang natutuhan sa pamilya na may impluwensiya sa kaniyang pagkatao', 1, '12 to 13 (9 days)', NULL),
  ('Values Education', 7, 'G7-023', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng palagiang pagsangguni sa mga magulang o tagapangalaga tungkol sa mga karanasan kaugnay ng mga natutuhang pagpapahalaga - Naipaliliwanag na ang pamilya bilang sandigan ng mga pagpapahalaga ay may gampanin na hubugin ang mga anak sa mga pagpapahalaga', 1, '12 to 13 (9 days)', NULL),
  ('Values Education', 7, 'G7-024', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng palagiang pagsangguni sa mga magulang o tagapangalaga tungkol sa mga karanasan kaugnay ng mga natutuhang pagpapahalaga - Nailalapat ang mga natutuhang pagpapahalaga sa mga situwasyong kinakaharap', 1, '12 to 13 (9 days)', NULL),
  ('Values Education', 7, 'G7-025', 'Nakapagsasanay sa pagiging matiyaga sa pamamagitan ng pagsasaalang-alang sa mga kahalagahan at kahihinatnan ng pagtupad sa sariling tungkulin sa pamilyang kinabibilangan - Natutukoy ang mga tungkulin sa pamilya na nararapat tuparin', 2, '1 (5 days)', NULL),
  ('Values Education', 7, 'G7-026', 'Nakapagsasanay sa pagiging matiyaga sa pamamagitan ng pagsasaalang-alang sa mga kahalagahan at kahihinatnan ng pagtupad sa sariling tungkulin sa pamilyang kinabibilangan - Naipaliliwanag na ang pagtupad sa mga tungkulin sa pamilya ay nakapaglilinang ng mga mabuting gawi, positibong pagtingin sa sarili, at nakapagpapatibay ng ugnayan sa pamilya', 2, '1 (5 days)', NULL),
  ('Values Education', 7, 'G7-027', 'Nakapagsasanay sa pagiging matiyaga sa pamamagitan ng pagsasaalang-alang sa mga kahalagahan at kahihinatnan ng pagtupad sa sariling tungkulin sa pamilyang kinabibilangan - Naisasakilos ang pagtupad sa mga tungkulin sa pamilyang kinabibilangan', 2, '1 (5 days)', NULL),
  ('Values Education', 7, 'G7-028', 'Nakapagsasanay sa pagiging mapagmahal sa pamamagitan ng palagiang paglingap sa kalagayan ng mga kasapi ng pamilya - Nakakikilala sa pamilya bilang likas na institusyon ng pagmamahalan', 2, '2 to 3 (10 days)', NULL),
  ('Values Education', 7, 'G7-029', 'Nakapagsasanay sa pagiging mapagmahal sa pamamagitan ng palagiang paglingap sa kalagayan ng mga kasapi ng pamilya - Naipaliliwanag na ang pamilya bilang likas na institusyon ng pagmamahalan ay pundasyon ng lipunan na humuhubog sa pagkatao, mabubuting gawi at pakikipagkapuwa tungo sa makabuluhang buhay', 2, '2 to 3 (10 days)', NULL),
  ('Values Education', 7, 'G7-030', 'Nakapagsasanay sa pagiging mapagmahal sa pamamagitan ng palagiang paglingap sa kalagayan ng mga kasapi ng pamilya - Naisasakilos ang wastong paraan ng pagmamahal sa mga kasapi ng pamilya', 2, '2 to 3 (10 days)', NULL),
  ('Values Education', 7, 'G7-031', 'Naisasabuhay ang pagiging madasalin sa pamamagitan ng kusang paghihikayat sa sama-samang pananalangin ng pamilya sa anumang situwasyon - Natutukoy ang kahalagahan ng sama-samang pananalangin ng pamilya', 2, '4 (5 days)', NULL),
  ('Values Education', 7, 'G7-032', 'Naisasabuhay ang pagiging madasalin sa pamamagitan ng kusang paghihikayat sa sama-samang pananalangin ng pamilya sa anumang situwasyon - Nahihinuha na ang sama-samang pananalangin ng pamilya ay nakatutulong sa pagpapatatag ng pananampalataya at ugnayan ng mga kasapi nito', 2, '4 (5 days)', NULL),
  ('Values Education', 7, 'G7-033', 'Naisasabuhay ang pagiging madasalin sa pamamagitan ng kusang paghihikayat sa sama-samang pananalangin ng pamilya sa anumang situwasyon - Naisasakilos ang sariling paraan ng pakikibahagi sa sama-samang pananalangin ng pamilya', 2, '4 (5 days)', NULL),
  ('Values Education', 7, 'G7-034', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pagninilay at pagsangguni sa mga taong may alam tungkol sa moral na pamumuhay - Nakakikilala ng mga paraan ng paghubog ng konsensiya gabay ang pananampalataya ng pamilya', 2, '5 to 6 (8 days)', NULL),
  ('Values Education', 7, 'G7-035', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pagninilay at pagsangguni sa mga taong may alam tungkol sa moral na pamumuhay - Nahihinuha na ang paghubog ng konsensiya gabay ang pananampalataya ng pamilya ay makatutulong sa paggabay ng isip sa pagkilatis ng kabutihan o kasamaan ng kilos batay sa likas na batas moral upang matiyak ang palagiang pagkiling sa kabutihan', 2, '5 to 6 (8 days)', NULL),
  ('Values Education', 7, 'G7-036', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pagninilay at pagsangguni sa mga taong may alam tungkol sa moral na pamumuhay - Naisasakilos ang gawain na nagpapakita ng paghubog ng konsensiya gabay ang pananampalataya ng pamilya', 2, '5 to 6 (8 days)', NULL),
  ('Values Education', 7, 'G7-037', 'Nakapagsasanay sa pagiging mapagmalasakit sa pamamagitan ng pagpapalaganap ng mga gawaing pampamilya ng wastong pagtugon sa pagbabago ng klima (climate change) - Naipahahayag ang mga wastong pagtugon ng pamilya sa pagbabago ng klima (climate change)', 2, '7 (5 days)', NULL),
  ('Values Education', 7, 'G7-038', 'Nakapagsasanay sa pagiging mapagmalasakit sa pamamagitan ng pagpapalaganap ng mga gawaing pampamilya ng wastong pagtugon sa pagbabago ng klima (climate change) - Naipaliliwanag na ang pagtugon ng pamilya sa pagbabago ng klima (climate change) ay pagtupad sa mga tungkulin nitong makiisa sa mga pandaigdigang gawain upang wastong mapamahalaan ang mga epekto nito sa kapaligiran', 2, '7 (5 days)', NULL),
  ('Values Education', 7, 'G7-039', 'Nakapagsasanay sa pagiging mapagmalasakit sa pamamagitan ng pagpapalaganap ng mga gawaing pampamilya ng wastong pagtugon sa pagbabago ng klima (climate change) - Naisasakilos ang mga sariling paraan ng wastong pagtugon ng pamilyang kinabibilangan sa pagbabago ng klima (climate change)', 2, '7 (5 days)', NULL),
  ('Values Education', 7, 'G7-040', 'Nakapagsasanay sa nasyonalismo sa pamamagitan ng pagpapalaganap ng kahalagahan ng mga pambansang pagdiriwang at kontribusyon ng mga bayani, paglalagay ng watawat at mga pambansang simbolo na naaayon sa batas - Natutukoy ang mga paraan ng pamilyang kinabibilangan sa pagtupad ng tungkulin nito sa bayan', 2, '8 to 9 (10 days)', NULL),
  ('Values Education', 7, 'G7-041', 'Nakapagsasanay sa nasyonalismo sa pamamagitan ng pagpapalaganap ng kahalagahan ng mga pambansang pagdiriwang at kontribusyon ng mga bayani, paglalagay ng watawat at mga pambansang simbolo na naaayon sa batas - Naipaliliwanag na ang mga tungkulin ng pamilya sa bayan ay paraan upang magbigay ng kontribusyon sa kabutihan, katiwasayan, kapayapaan at kaunlaran ng pamayanan na magiging matibay na pundasyon ng lipunang Pilipino', 2, '8 to 9 (10 days)', NULL),
  ('Values Education', 7, 'G7-042', 'Nakapagsasanay sa nasyonalismo sa pamamagitan ng pagpapalaganap ng kahalagahan ng mga pambansang pagdiriwang at kontribusyon ng mga bayani, paglalagay ng watawat at mga pambansang simbolo na naaayon sa batas - Naisasakilos ang sariling paraan bilang bahagi ng pagtupad sa tungkulin ng pamilyang kinabibilangan sa bayan', 2, '8 to 9 (10 days)', NULL),
  ('Values Education', 7, 'G7-043', 'Nakapagsasanay sa tiwala sa sarili sa pamamagitan ng palagiang pagkilos ng mga paraan na tutugon sa kaniyang layunin sa pagpapaunlad ng talento at hilig - Natutukoy ang mga sariling talento at hilig kaagapay ang kapuwa', 2, '10 (5 days)', NULL),
  ('Values Education', 7, 'G7-044', 'Nakapagsasanay sa tiwala sa sarili sa pamamagitan ng palagiang pagkilos ng mga paraan na tutugon sa kaniyang layunin sa pagpapaunlad ng talento at hilig - Naipaliliwanag na ang pagtuklas at pagpapaunlad ng sariling talento at hilig kaagapay ang kapuwa ay nakatutulong sa pagtupad sa mga tungkulin, pagbuo ng pananaw sa ninanais na propesyon (kursong akademiko, teknikal-bokasyonal, sining at isports, negosyo o hanapbuhay), at paglilingkod sa kapuwa ayon sa kaniyang kakayahan', 2, '10 (5 days)', NULL),
  ('Values Education', 7, 'G7-045', 'Nakapagsasanay sa tiwala sa sarili sa pamamagitan ng palagiang pagkilos ng mga paraan na tutugon sa kaniyang layunin sa pagpapaunlad ng talento at hilig - Naisasakilos ang pagpapaunlad ng mga sariling talento at hilig kaagapay ang kapuwa', 2, '10 (5 days)', NULL),
  ('Values Education', 7, 'G7-046', 'Nakapagsasanay sa pagiging mapagmalasakit sa pamamagitan ng pakikisangkot sa mga gawaing nagpapabuti sa kalagayan ng mga mamamayan ayon sa kaniyang kakayahan - Nakakikilala ng katangian ng pagpapakatao', 2, '11 (5 days)', NULL),
  ('Values Education', 7, 'G7-047', 'Nakapagsasanay sa pagiging mapagmalasakit sa pamamagitan ng pakikisangkot sa mga gawaing nagpapabuti sa kalagayan ng mga mamamayan ayon sa kaniyang kakayahan - Naipaliliwanag na ang pagpapaunlad ng sarili batay sa katangian ng pagpapakatao para sa bayan ay makatutulong sa paggampan sa kaniyang mga tungkulin para sa pagtupad ng kaniyang misyon sa buhay na maglingkod', 2, '11 (5 days)', NULL),
  ('Values Education', 7, 'G7-048', 'Nakapagsasanay sa pagiging mapagmalasakit sa pamamagitan ng pakikisangkot sa mga gawaing nagpapabuti sa kalagayan ng mga mamamayan ayon sa kaniyang kakayahan - Nailalapat ang katangian ng pagpapakatao sa pagtupad ng kaniyang mga tungkulin', 2, '11 (5 days)', NULL),
  ('Values Education', 7, 'G7-049', 'Nakapagsasanay sa pagiging mapagpakumbaba sa pamamagitan ng sariling kilos ng pagpapatawad at pakikipagkasundo sa kapuwa - Natutukoy ang mga kilos na nagpapakita ng pagpapatawad at pakikipagkasundo sa kapuwa', 2, '12 (5 days)', NULL),
  ('Values Education', 7, 'G7-050', 'Nakapagsasanay sa pagiging mapagpakumbaba sa pamamagitan ng sariling kilos ng pagpapatawad at pakikipagkasundo sa kapuwa - Nahihinuha na ang pagpapatawad at pakikipagkasundo sa kapuwa ay nakatutulong sa pagbuo ng sarili at nasirang ugnayan sa pamilya at kapuwa kung isinasagawa nang may kababaang-loob', 2, '12 (5 days)', NULL),
  ('Values Education', 7, 'G7-051', 'Nakapagsasanay sa pagiging mapagpakumbaba sa pamamagitan ng sariling kilos ng pagpapatawad at pakikipagkasundo sa kapuwa - Nailalapat ang mga sariling kilos ng pagpapatawad at pakikipagkasundo sa kapuwa', 2, '12 (5 days)', NULL),
  ('Values Education', 7, 'G7-052', 'Nakapagsasanay sa pagiging matapat sa pamamagitan ng maayos na pakikipag-ugnayan at bukas na komunikasyon sa kapuwa - Natutukoy ang mga positibong dulot ng mabuting pakikipagkaibigan', 2, '13 to 14 (5 days)', NULL),
  ('Values Education', 7, 'G7-053', 'Nakapagsasanay sa pagiging matapat sa pamamagitan ng maayos na pakikipag-ugnayan at bukas na komunikasyon sa kapuwa - Nahihinuha na ang pakikipagkaibigan ay nakatutulong sa paghubog ng matatag na sariling pagkakakilanlan, pagpapaunlad ng pagkatao, at mapayapang pakikipag-ugnayan sa kapuwa dahil nabuo ito sa kagustuhang makipag-ugnayan bunga ng pagmamahal', 2, '13 to 14 (5 days)', NULL),
  ('Values Education', 7, 'G7-054', 'Nakapagsasanay sa pagiging matapat sa pamamagitan ng maayos na pakikipag-ugnayan at bukas na komunikasyon sa kapuwa - Naisasakilos ang mga paraan sa pagpapatatag ng pakikipagkaibigan', 2, '13 to 14 (5 days)', NULL)
) AS v(area, grade_level, lc_code, competency_text, term, week, domain)
JOIN procurements.sms_learning_areas a ON lower(btrim(a.name)) = lower(btrim(v.area))
ON CONFLICT (learning_area_id, grade_level, lc_code) DO NOTHING;

/* Verification: after all 22 parts, seeded_entries = 6718. */
SELECT count(*) AS seeded_entries,
       count(DISTINCT learning_area_id) AS learning_areas
FROM procurements.sms_competency_catalogue
WHERE lc_code ~ '^(K|G[0-9]+)-[0-9]{3}$';
